def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    try:
        if not keys:
            return list(self._data.values())
        else:
            return [self._data[key] for key in keys]
    except KeyError as e:
        raise ValueError(f"Key {e} not found in the record.") from e
    except TypeError as e:
        raise ValueError(f"Invalid key type: {e}") from e

def data(self, *keys):
    result = {}
    if not keys:
        return dict(self._data)
    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(self._data):
                raise IndexError(f"Index {key} is out of bounds")
            result[list(self._data.keys())[key]] = list(self._data.values())[key]
        else:
            result[key] = self._data.get(key, None)
    return result

