def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    if not isinstance(name, str) or not name:
        raise ValueError("Name must be a non-empty string.")
    if not isinstance(fields, dict):
        raise ValueError("Fields must be a dictionary.")
    if not isinstance(srid_map, dict):
        raise ValueError("SRID map must be a dictionary.")

    class Point:
        def __init__(self, **kwargs):
            for field, field_type in fields.items():
                if field not in kwargs:
                    raise ValueError(f"Missing required field: {field}")
                if not isinstance(kwargs[field], field_type):
                    raise ValueError(f"Field {field} must be of type {field_type.__name__}")
                setattr(self, field, kwargs[field])
            self.srid_map = srid_map

        def __repr__(self):
            field_values = ', '.join(f"{field}={getattr(self, field)!r}" for field in fields)
            return f"{name}({field_values})"

    Point.__name__ = name
    return Point

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            import warnings
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    if not cmd:
        raise ValueError("Command tuple cannot be empty")

    # Convert the command to a list for mutability
    cmd_list = list(cmd)

    # Check if the first element is a script with a shebang
    if cmd_list[0].endswith('.py'):
        try:
            with open(cmd_list[0], 'r', encoding='utf-8') as file:
                first_line = file.readline().strip()
                if first_line.startswith('#!'):
                    # Extract the interpreter from the shebang
                    interpreter = first_line[2:].split()[0]
                    # Insert the interpreter at the beginning of the command
                    cmd_list.insert(0, interpreter)
        except FileNotFoundError:
            raise FileNotFoundError(f"The script {cmd_list[0]} does not exist")
        except Exception as e:
            raise RuntimeError(f"An error occurred while reading the script {cmd_list[0]}: {e}")

    # Convert the list back to a tuple
    return tuple(cmd_list)

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            k = key(*args, **kwargs)
            if lock:
                with lock:
                    if k in cache:
                        return cache[k]
                    result = func(*args, **kwargs)
                    cache[k] = result
                    return result
            else:
                if k in cache:
                    return cache[k]
                result = func(*args, **kwargs)
                cache[k] = result
                return result
        return wrapper
    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
    """
    from functools import lru_cache as _lru_cache

    if not isinstance(maxsize, int) or maxsize < 0:
        raise ValueError("maxsize must be a non-negative integer")
    if not isinstance(typed, bool):
        raise ValueError("typed must be a boolean")

    def decorator(func):
        return _lru_cache(maxsize=maxsize, typed=typed)(func)

    return decorator

