def difference(d1, d2, level=-1):
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise ValueError("Both d1 and d2 must be dictionaries.")
    if level == 0:
        return {}

    diff = {}
    for key in d1:
        if key not in d2:
            diff[key] = d1[key]
        elif isinstance(d1[key], dict) and isinstance(d2[key], dict):
            sub_diff = difference(d1[key], d2[key], level - 1)
            if sub_diff:
                diff[key] = sub_diff
        elif d1[key] != d2[key]:
            diff[key] = d1[key]
    return diff

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    try:
        if all(0 <= c < dim for c, dim in zip(coord, self.shape)):
            self.histogram[tuple(coord)] += weight
    except (TypeError, ValueError) as e:
        # Handle cases where coord is not iterable or weight is not a number
        raise ValueError("Invalid coordinate or weight") from e
    except IndexError:
        # This should not happen due to the check, but just in case
        pass

def _validate_labels(labels):
    import re
    from collections.abc import Hashable

    class ValidationError(Exception):
        def __init__(self, messages):
            self.messages = messages
            super().__init__(f"Validation errors: {messages}")

    key_regex = re.compile(r'^[a-zA-Z0-9._-]+$')
    value_regex = re.compile(r'^[a-zA-Z0-9._-]+$')

    errors = []

    for key, value in labels.items():
        if not isinstance(key, Hashable):
            errors.append({str(key): 'expected hashable object'})
            continue

        key_str = str(key)
        if not key_regex.match(key_str):
            errors.append({key_str: f"Label key '{key_str}' does not match the regex '^[a-zA-Z0-9._-]+$'"})

        if not isinstance(value, (str, bytes)):
            errors.append({str(value): 'expected string or bytes-like object'})
            continue

        value_str = str(value)
        if not value_regex.match(value_str):
            errors.append({value_str: f"Label value '{value_str}' does not match the regex '^[a-zA-Z0-9._-]+$'"})


    if errors:
        raise ValidationError(errors)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    if not isinstance(manifest_dict, dict):
        raise ValueError("manifest_dict must be a dictionary")

    observer_schema = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            observer_schema[key] = generate_default_observer_schema_dict(value)
        elif isinstance(value, list):
            observer_schema[key] = [generate_default_observer_schema_dict(item) if isinstance(item, dict) else None for item in value]
        else:
            if first_level and key in ['apiVersion', 'kind', 'metadata']:
                observer_schema[key] = value
            else:
                observer_schema[key] = None

    return observer_schema

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    if not isinstance(last_applied_manifest, list) or not isinstance(observer_schema, list) or not isinstance(response, list):
        raise ValueError("All arguments must be lists")

    for obs_schema, resp_item in zip(observer_schema, response):
        if isinstance(obs_schema, dict) and isinstance(resp_item, dict):
            # Assuming there's a corresponding function to handle dictionaries
            update_last_applied_manifest_dict_from_resp(last_applied_manifest, obs_schema, resp_item)
        elif isinstance(obs_schema, list) and isinstance(resp_item, list):
            update_last_applied_manifest_list_from_resp(last_applied_manifest, obs_schema, resp_item)
        else:
            for i, obs_field in enumerate(obs_schema):
                if i >= len(last_applied_manifest):
                    last_applied_manifest.append(None)
                if last_applied_manifest[i] is None:
                    last_applied_manifest[i] = resp_item[i] if i < len(resp_item) else None

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    for field, schema in observer_schema.items():
        if field not in response:
            raise KeyError(f"The observed field '{field}' is not present in the Kubernetes response")
        if field not in last_applied_manifest:
            last_applied_manifest[field] = response[field]
        if isinstance(schema, dict) and isinstance(response[field], dict):
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[field], schema, response[field]
            )

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    try:
        if not hasattr(app, 'spec') or not hasattr(app.spec, 'manifest'):
            raise ValueError("Application object does not contain a valid spec.manifest")

        default_schema = {}
        for resource_type, resource in app.spec.manifest.items():
            if resource_type not in app.spec.observer_schema:
                default_schema[resource_type] = {
                    "kind": resource.get("kind"),
                    "apiVersion": resource.get("apiVersion"),
                    "namespace": resource.get("metadata", {}).get("namespace"),
                    "name": resource.get("metadata", {}).get("name"),
                    "status": {}
                }
        return default_schema

    except Exception as e:
        raise RuntimeError(f"Failed to generate default observer schema: {e}")

