def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    if not isinstance(commands, (list, tuple)):
        raise ValueError("commands must be a list or tuple of command strings.")
    if not all(isinstance(cmd, str) for cmd in commands):
        raise ValueError("Each command in commands must be a string.")
    if not isinstance(args, (list, tuple)):
        raise ValueError("args must be a list or tuple of argument strings.")
    if not all(isinstance(arg, str) for arg in args):
        raise ValueError("Each argument in args must be a string.")
    if cwd is not None and not isinstance(cwd, str):
        raise ValueError("cwd must be a string or None.")
    if not isinstance(verbose, bool):
        raise ValueError("verbose must be a boolean.")
    if not isinstance(hide_stderr, bool):
        raise ValueError("hide_stderr must be a boolean.")
    if env is not None and not isinstance(env, dict):
        raise ValueError("env must be a dictionary or None.")

    full_command = list(commands) + list(args)
    try:
        if verbose:
            print(f"Running command: {' '.join(full_command)}")

        with subprocess.Popen(
            full_command,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE if hide_stderr else subprocess.STDOUT,
            text=True
        ) as process:
            output, _ = process.communicate()
            if process.returncode != 0:
                raise subprocess.CalledProcessError(process.returncode, full_command, output=output)
            if verbose:
                print(f"Command output:\n{output}")
            return output

    except FileNotFoundError as e:
        raise FileNotFoundError(f"Command not found: {full_command[0]}") from e
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Command failed with return code {e.returncode}: {e.cmd}\nOutput:\n{e.output}") from e
    except Exception as e:
        raise RuntimeError(f"An error occurred while running the command: {full_command}") from e

def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""
    if not isinstance(vcs, str):
        raise ValueError("VCS must be a string.")
    if not callable(method):
        raise ValueError("Method must be callable.")

    def decorator(func):
        func._vcs_handler = (vcs, method)
        return func

    return decorator

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    num_objects = 0
    good_objects = 0

    try:
        # Assuming self.root is the starting point of the hierarchy
        for obj in self.root.iterate_objects():
            num_objects += 1
            is_valid = True

            if validate_objects:
                if not obj.is_valid():
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: Object {obj.id} is not valid.")

            if check_digests:
                if not obj.check_digest():
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: Digest mismatch for object {obj.id}.")

            if is_valid:
                good_objects += 1

    except Exception as e:
        print(f"An error occurred during validation: {e}")

    return num_objects, good_objects

def validate_version_inventories(self, version_dirs):
    if not isinstance(version_dirs, list):
        raise ValueError("version_dirs must be a list of version directory names.")

    root_inventory = self.get_root_inventory()  # Assuming a method to get the root inventory
    content_digests_diff = {}

    for version in version_dirs:
        if not isinstance(version, str):
            raise ValueError("Each version in version_dirs must be a string.")

        try:
            version_inventory = self.get_version_inventory(version)  # Assuming a method to get version inventory
        except Exception as e:
            raise RuntimeError(f"Failed to retrieve inventory for version {version}: {str(e)}")

        for item, digest in version_inventory.items():
            if item not in root_inventory or root_inventory[item] != digest:
                if version not in content_digests_diff:
                    content_digests_diff[version] = {}
                content_digests_diff[version][item] = digest

    return content_digests_diff

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    try:
        if os.path.isfile(path):
            return 'file'
        elif os.path.isdir(path):
            namaste_files = [f for f in os.listdir(path) if f.startswith('0=')]
            if '0=ocfl_1.0' in namaste_files:
                return 'root'
            elif any(f.startswith('0=ocfl_object') for f in namaste_files):
                return 'object'
            else:
                return 'unknown directory type'
        else:
            return 'path does not exist'
    except Exception as e:
        return f'error: {str(e)}'

