        raise ValueError("The 'arg' parameter must be a string.")
    return value.replace('.', arg)

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not isinstance(string, str):
        raise ValueError("Input string must be a string.")
    if not isinstance(alphabet, list) or not all(isinstance(char, str) and len(char) == 1 for char in alphabet):
        raise ValueError("Alphabet must be a list of single-character strings.")
    if not alphabet:
        raise ValueError("Alphabet cannot be empty.")

    base = len(alphabet)
    result = 0
    for char in string:
        if char not in alphabet:
            raise ValueError(f"Character '{char}' in string is not in the alphabet.")
        digit_value = alphabet.index(char)
        result = result * base + digit_value
    return result

