def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import re
    import sys

    if platform == 'this':
        platform = 1 if sys.platform != 'win32' else 0

    if platform == 1:  # POSIX
        # Regex for POSIX shell-like splitting
        pattern = r"""(['"])(?:(?=(\\?))\2.)*?\1|\S+"""
    elif platform == 0:  # Windows/CMD
        # Regex for Windows CMD-like splitting
        pattern = r"""(["'])(?:(?=(\\?))\2.)*?\1|\S+"""
    else:
        raise ValueError("Unsupported platform value. Use 'this', 1, or 0.")

    try:
        return re.findall(pattern, s, re.UNICODE)
    except TypeError as e:
        raise TypeError("Input must be a string.") from e

def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None

    try:
        parts = frequency.split()
        if len(parts) != 2:
            raise ValueError("Frequency must be in the format 'number unit'")

        number = int(parts[0])
        unit = parts[1].lower()

        if unit in ['second', 'seconds']:
            return datetime.timedelta(seconds=number)
        elif unit in ['minute', 'minutes']:
            return datetime.timedelta(minutes=number)
        elif unit in ['hour', 'hours']:
            return datetime.timedelta(hours=number)
        elif unit in ['day', 'days']:
            return datetime.timedelta(days=number)
        elif unit in ['week', 'weeks']:
            return datetime.timedelta(weeks=number)
        else:
            raise ValueError(f"Unknown time unit: {unit}")

    except (ValueError, TypeError) as e:
        raise ValueError(f"Invalid frequency: {frequency}") from e

def make_find_paths(find_paths):
    def is_pattern(s):
        return '*' in s or '?' in s or '[' in s or ']' in s

    transformed_paths = []
    for path in find_paths:
        if not is_pattern(path) and ':' not in path:
            # Transform path fragment into a glob pattern
            transformed_path = f'sh:**/*{path}*/**'
        else:
            # Pass through existing patterns or paths with a colon untouched
            transformed_path = path
        transformed_paths.append(transformed_path)
    return transformed_paths

