def oneline(script, separator=" && "):
    """
    converts a script to one line command.
    This is useful to run a single ssh command and pass a one line script.

    :param script: A string or list of strings representing the script.
    :param separator: A string used to separate commands in the one-liner.
    :return: A single string with the script commands separated by the separator.
    """
    if isinstance(script, str):
        script = script.splitlines()
    elif not isinstance(script, list):
        raise ValueError("Script must be a string or a list of strings.")

    try:
        return separator.join(command.strip() for command in script if command.strip())
    except Exception as e:
        raise RuntimeError(f"An error occurred while converting script to one line: {e}")

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    if not isinstance(pattern, str):
        raise ValueError("The pattern must be a string.")

    if strip:
        pattern = pattern.strip()

    try:
        regex_pattern = re.compile(pattern)
