def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, list) or not all(isinstance(cmd, str) for cmd in commands):
        raise ValueError("Commands must be a list of strings.")
    if not isinstance(args, list) or not all(isinstance(arg, str) for arg in args):
        raise ValueError("Arguments must be a list of strings.")

    full_command = commands + args
    try:
        if verbose:
            print(f"Running command: {' '.join(full_command)}")

        stderr = subprocess.DEVNULL if hide_stderr else None
        result = subprocess.run(full_command, cwd=cwd, env=env, capture_output=True, text=True, stderr=stderr)

        if verbose:
            print(f"Command output:\n{result.stdout}")

        if result.returncode != 0:
            raise subprocess.CalledProcessError(result.returncode, full_command, output=result.stdout, stderr=result.stderr)

        return result.stdout
    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Command failed with error:\n{e.stderr}")
        raise
    except Exception as e:
        if verbose:
            print(f"An error occurred: {e}")
        raise

