def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if not isinstance(parser_dict, dict):
        raise ValueError("parser_dict must be a dictionary")

    if 'include' not in parser_dict:
        return parser_dict

    include_directive = parser_dict['include']
    if not isinstance(include_directive, dict):
        raise ValueError("The 'include' directive must be a dictionary")

    for key, value in include_directive.items():
        if not isinstance(value, dict):
            raise ValueError(f"The value for '{key}' in the 'include' directive must be a dictionary")
        parser_dict[key] = value

    del parser_dict['include']
    return parser_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    try:
        # Assuming 'self.spec' is a dictionary containing the specification
        defaults = {}
        for arg, details in self.spec.items():
            if 'default' in details:
                defaults[arg] = details['default']
        return defaults
    except AttributeError:
        raise ValueError("Instance does not have a 'spec' attribute.")
    except Exception as e:
        raise RuntimeError(f"An error occurred while resolving defaults: {e}")

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """
    try:
        # Assuming deprecated_args is an attribute of the class
        return self.deprecated_args
    except AttributeError:
        # Handle the case where deprecated_args is not defined
