def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    if not isinstance(args, dict):
        raise ValueError("Input args must be a dictionary")

    control_args = {}
    nested_args = {}

    for key, value in args.items():
        if key.startswith('control_'):
            control_args[key] = value
        elif key.startswith('custom_'):
            nested_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be a dictionary")

    if extra_vars is None:
        extra_vars = []

    if not isinstance(extra_vars, list):
        raise ValueError("extra_vars must be a list")

    for item in extra_vars:
        if not isinstance(item, dict):
            raise ValueError("Each item in extra_vars must be a dictionary")
        vars_dict.update(item)

    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess

    if not playbook_path:
        raise ValueError("playbook_path is required")

    command = ['ansible-playbook', playbook_path]

    if verbose:
        command.extend(['-v'] * verbose)

    if extra_vars:
        extra_vars_str = ','.join(f'{k}={v}' for k, v in extra_vars.items())
        command.extend(['--extra-vars', extra_vars_str])

    if ansible_args:
        for arg, value in ansible_args.items():
            if value is None:
                command.append(f'--{arg}')
            else:
                command.extend([f'--{arg}', str(value)])

    try:
        result = subprocess.run(command, check=True, text=True, capture_output=True)
        return result.stdout
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Ansible playbook failed with return code {e.returncode}: {e.stderr}") from e
    except Exception as e:
        raise RuntimeError(f"An error occurred while running the ansible playbook: {e}") from e

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if not isinstance(values_dict, dict):
        raise ValueError("values_dict must be a dictionary")

    # Example conversion logic, this should be customized based on actual requirements
    conversion_rules = {
        'main': {
            'age': int,
            'height': float,
            'is_active': bool
        },
        'virsh': {
            'memory': int,
            'vcpus': int,
            'autostart': bool
        },
        'ospd': {
            'port': int,
            'use_ssl': bool,
            'timeout': float
        }
    }

    if parser_name not in conversion_rules:
        raise ValueError(f"No conversion rules defined for parser_name: {parser_name}")

    rules = conversion_rules[parser_name]
    for key, value in values_dict.items():
        if key in rules:
            try:
                values_dict[key] = rules[key](value)
            except (ValueError, TypeError) as e:
                raise ValueError(f"Error converting {key} to {rules[key].__name__}: {e}")

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def flatten_dict(d, parent_key='', sep='_'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    try:
        spec_path = os.path.join(plugin_dir, 'plugin_spec.json')
        if not os.path.exists(spec_path):
            raise FileNotFoundError(f"Plugin spec file not found at {spec_path}")

        with open(spec_path, 'r') as file:
            plugin_spec = json.load(file)

        return flatten_dict(plugin_spec)

    except FileNotFoundError as e:
        print(f"Error: {e}")
        return {}
    except json.JSONDecodeError as e:
        print(f"Error decoding JSON from {spec_path}: {e}")
        return {}
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return {}

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    config_path = os.getenv('CONFIG_PATH')
    if config_path is None:
        try:
            # Assuming a default config path, this should be adjusted as necessary
            default_config_path = '/path/to/default/config'
            os.environ['CONFIG_PATH'] = default_config_path
        except Exception as e:
            raise RuntimeError(f"Failed to set CONFIG_PATH environment variable: {e}")

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise ValueError("Both path and root must be strings.")

    if not path.startswith(root):
        raise ValueError("Path does not start with the specified root.")

    stripped_path = path[len(root):]
    # Remove the separator if the stripped path is not empty
    if stripped_path and stripped_path.startswith('/'):
        stripped_path = stripped_path[1:]

    return stripped_path
